---
apiVersion: v1
kind: ServiceAccount
metadata:
  name: {{ .Values.name | default "infisical-csi-provider" }}
  namespace: {{ .Values.namespace | default "kube-system" }}
  labels:
    app: {{ .Values.name | default "infisical-csi-provider" }}
    {{- with .Values.labels }}
    {{- toYaml . | nindent 4 }}
    {{- end }}
---
apiVersion: rbac.authorization.k8s.io/v1
kind: ClusterRole
metadata:
  name: {{ .Values.name | default "infisical-csi-provider" }}
  labels:
    app: {{ .Values.name | default "infisical-csi-provider" }}
    {{- with .Values.labels }}
    {{- toYaml . | nindent 4 }}
    {{- end }}
rules:
- apiGroups: [""]
  resources: ["serviceaccounts/token"]
  verbs: ["create"]
{{- if .Values.readWindow.enabled }}
# Reading pod status is what bounds the read window: the start time of a pod's containers cannot be
# forged by the pod itself. Watched rather than fetched per mount, since the rotation reconciler calls
# the provider for every pod on every poll. A field selector scopes the cache to one node, but RBAC
# cannot express one, so the grant is cluster-wide and only made when the feature is on.
- apiGroups: [""]
  resources: ["pods"]
  verbs: ["get", "list", "watch"]
{{- end }}
---
apiVersion: rbac.authorization.k8s.io/v1
kind: ClusterRoleBinding
metadata:
  name: {{ .Values.name | default "infisical-csi-provider" }}
  labels:
    app: {{ .Values.name | default "infisical-csi-provider" }}
    {{- with .Values.labels }}
    {{- toYaml . | nindent 4 }}
    {{- end }}
roleRef:
  apiGroup: rbac.authorization.k8s.io
  kind: ClusterRole
  name: {{ .Values.name | default "infisical-csi-provider" }}
subjects:
- kind: ServiceAccount
  name: {{ .Values.name | default "infisical-csi-provider" }}
  namespace: {{ .Values.namespace | default "kube-system" }}

apiVersion: apps/v1
kind: DaemonSet
metadata:
  labels:
    app: {{ .Values.name | default "infisical-csi-provider" }}
    {{- with .Values.labels }}
    {{- toYaml . | nindent 4 }}
    {{- end }}
  name: {{ .Values.name | default "infisical-csi-provider" }}
  namespace: {{ .Values.namespace | default "kube-system" }}
spec:
  updateStrategy:
    type: {{ .Values.updateStrategy | default "RollingUpdate" }}
  selector:
    matchLabels:
      app: {{ .Values.name | default "infisical-csi-provider" }}
  template:
    metadata:
      labels:
        app: {{ .Values.name | default "infisical-csi-provider" }}
        {{- with .Values.podLabels }}
        {{- toYaml . | nindent 8 }}
        {{- end }}
    spec:
      serviceAccountName: {{ .Values.name | default "infisical-csi-provider" }}
      {{- with .Values.tolerations }}
      tolerations:
      {{- toYaml . | nindent 6 }}
      {{- end }}
      containers:
        - name: {{ .Values.name | default "infisical-csi-provider" }}
          image: {{ .Values.image.repository }}:{{ .Values.image.tag | default "latest" }}
          imagePullPolicy: {{ .Values.image.pullPolicy | default "Never" }}
          args:
            {{- with .Values.args }}
            {{- toYaml . | nindent 12 }}
            {{- end }}
          resources:
            {{- toYaml .Values.resources | nindent 12 }}
{{- if .Values.readWindow.enabled }}
          env:
            # Scopes the pod watch to this node. Without it the provider reads pods from the API server
            # on every mount instead.
            - name: NODE_NAME
              valueFrom:
                fieldRef:
                  fieldPath: spec.nodeName
{{- end }}
          volumeMounts:
            - name: providervol
              mountPath: {{ .Values.providerVolume.mountPath | default "/provider" }}
          livenessProbe:
            {{- toYaml .Values.livenessProbe | nindent 12 }}
          readinessProbe:
            {{- toYaml .Values.readinessProbe | nindent 12 }}
      volumes:
        - name: providervol
          hostPath:
            path: {{ .Values.providerVolume.hostPath | default "/etc/kubernetes/secrets-store-csi-providers" }}
      nodeSelector:
        {{- toYaml .Values.nodeSelector | nindent 8 }}

package window

import (
	"context"
	"os"
	"testing"
	"time"

	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/tools/clientcmd"
)

// Runs the window evaluation against a real cluster, on a pod that really restarts. The unit tests
// use fabricated statuses; this checks the assumptions behind them, in particular that a container
// restarted in place keeps the pod UID, increments restartCount, and gets a fresh startedAt.
//
//	WINDOW_IT_CONTEXT=<kube context> [WINDOW_IT_NAMESPACE=<ns>] go test ./internal/window/ -run Integration -v
func TestIntegrationWindowFollowsARealRestart(t *testing.T) {
	kubeContext := os.Getenv("WINDOW_IT_CONTEXT")
	if kubeContext == "" {
		t.Skip("set WINDOW_IT_CONTEXT to run against a cluster")
	}
	namespace := os.Getenv("WINDOW_IT_NAMESPACE")
	if namespace == "" {
		namespace = "default"
	}

	clientset := clientsetFor(t, kubeContext)
	ctx := context.Background()
	const duration = 15 * time.Second

	name := "window-it"
	_ = clientset.CoreV1().Pods(namespace).Delete(ctx, name, metav1.DeleteOptions{})
	waitGone(t, clientset, namespace, name)

	// Exits non-zero shortly after starting, so the kubelet restarts it in place and we observe a
	// second container generation without a new pod.
	pod := &corev1.Pod{
		ObjectMeta: metav1.ObjectMeta{Name: name, Namespace: namespace},
		Spec: corev1.PodSpec{
			RestartPolicy: corev1.RestartPolicyAlways,
			Containers: []corev1.Container{{
				Name:    "app",
				Image:   "public.ecr.aws/docker/library/busybox:1.36",
				Command: []string{"sh", "-c", "sleep 30; exit 1"},
			}},
		},
	}
	if _, err := clientset.CoreV1().Pods(namespace).Create(ctx, pod, metav1.CreateOptions{}); err != nil {
		t.Fatalf("create pod: %v", err)
	}
	t.Cleanup(func() {
		_ = clientset.CoreV1().Pods(namespace).Delete(context.Background(), name, metav1.DeleteOptions{})
	})

	pods := apiPods{clientset: clientset}
	var sawOpen, sawClosed, sawReopened bool

	deadline := time.Now().Add(3 * time.Minute)
	for time.Now().Before(deadline) && !sawReopened {
		open, err := IsOpen(ctx, pods, Pod{Namespace: namespace, Name: name}, duration)
		if err != nil {
			t.Logf("IsOpen: %v", err)
			time.Sleep(3 * time.Second)
			continue
		}
		restarts := restartCount(t, clientset, namespace, name)
		t.Logf("open=%-5v restarts=%d", open, restarts)

		switch {
		case open && !sawOpen:
			sawOpen = true
		case !open && sawOpen:
			sawClosed = true
		case open && sawClosed && restarts > 0:
			sawReopened = true
		}
		time.Sleep(3 * time.Second)
	}

	if !sawOpen {
		t.Fatal("never saw an open window after the pod started")
	}
	if !sawClosed {
		t.Fatal("window never closed while the container kept running")
	}
	if !sawReopened {
		t.Fatal("window never reopened after the container restarted")
	}
}

func clientsetFor(t *testing.T, kubeContext string) kubernetes.Interface {
	t.Helper()
	rules := clientcmd.NewDefaultClientConfigLoadingRules()
	overrides := &clientcmd.ConfigOverrides{CurrentContext: kubeContext}
	restConfig, err := clientcmd.NewNonInteractiveDeferredLoadingClientConfig(rules, overrides).ClientConfig()
	if err != nil {
		t.Fatalf("kube config: %v", err)
	}
	clientset, err := kubernetes.NewForConfig(restConfig)
	if err != nil {
		t.Fatalf("kube client: %v", err)
	}
	return clientset
}

func restartCount(t *testing.T, clientset kubernetes.Interface, namespace, name string) int32 {
	t.Helper()
	pod, err := clientset.CoreV1().Pods(namespace).Get(context.Background(), name, metav1.GetOptions{})
	if err != nil {
		return -1
	}
	var restarts int32
	for _, status := range pod.Status.ContainerStatuses {
		restarts += status.RestartCount
	}
	return restarts
}

func waitGone(t *testing.T, clientset kubernetes.Interface, namespace, name string) {
	t.Helper()
	for i := 0; i < 60; i++ {
		if _, err := clientset.CoreV1().Pods(namespace).Get(context.Background(), name, metav1.GetOptions{}); err != nil {
			return
		}
		time.Sleep(2 * time.Second)
	}
	t.Fatalf("pod %s/%s did not go away", namespace, name)
}

package kube

import (
	"context"
	"testing"

	corev1 "k8s.io/api/core/v1"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	apitypes "k8s.io/apimachinery/pkg/types"
	"k8s.io/client-go/kubernetes/fake"
	listers "k8s.io/client-go/listers/core/v1"
	"k8s.io/client-go/tools/cache"
)

func pod(uid, startedAt string) *corev1.Pod {
	return &corev1.Pod{ObjectMeta: metav1.ObjectMeta{
		Name: "a-pod", Namespace: "ns", UID: apitypes.UID(uid),
		Annotations: map[string]string{"startedAt": startedAt},
	}}
}

func listerHolding(t *testing.T, pods ...*corev1.Pod) listers.PodLister {
	t.Helper()
	indexer := cache.NewIndexer(cache.MetaNamespaceKeyFunc, cache.Indexers{})
	for _, p := range pods {
		if err := indexer.Add(p); err != nil {
			t.Fatalf("add: %v", err)
		}
	}
	return listers.NewPodLister(indexer)
}

// A pod name can be reused: the cache may still hold the previous incarnation, whose start time
// belongs to a lifetime that has ended. Serving it would report a long-closed window for a pod that
// just started, so a UID mismatch has to reach the API server instead.
func TestStaleCacheEntryFallsBackToTheApiServer(t *testing.T) {
	cached := pod("old-uid", "yesterday")
	fresh := pod("new-uid", "now")

	p := &Pods{clientset: fake.NewClientset(fresh), lister: listerHolding(t, cached)}

	got, err := p.Get(context.Background(), "ns", "a-pod", "new-uid")
	if err != nil {
		t.Fatalf("Get: %v", err)
	}
	if string(got.UID) != "new-uid" {
		t.Fatalf("expected the fresh pod from the API server, got UID %q", got.UID)
	}
}

// A mount request can overlap deletion and same-name recreation: the request still carries the old
// UID while the cache and the API server have already moved to the replacement. Returning the
// replacement would evaluate the window against its fresh start time and serve secrets to a mount from
// an ended lifetime, so the fallback must reject a UID mismatch rather than trust the name.
func TestApiServerFallbackRejectsAUidMismatch(t *testing.T) {
	replacement := pod("new-uid", "now")

	p := &Pods{clientset: fake.NewClientset(replacement), lister: listerHolding(t, replacement)}

	_, err := p.Get(context.Background(), "ns", "a-pod", "old-uid")
	if !apierrors.IsNotFound(err) {
		t.Fatalf("expected a NotFound for the departed incarnation, got %v", err)
	}
}

func TestCacheHitWhenTheUidMatches(t *testing.T) {
	cached := pod("same-uid", "now")
	// The API server deliberately holds nothing, so a hit can only come from the cache.
	p := &Pods{clientset: fake.NewClientset(), lister: listerHolding(t, cached)}

	got, err := p.Get(context.Background(), "ns", "a-pod", "same-uid")
	if err != nil {
		t.Fatalf("Get: %v", err)
	}
	if got.Annotations["startedAt"] != "now" {
		t.Fatalf("expected the cached pod, got %+v", got.Annotations)
	}
}

// Without a node name there is no watch to scope, so every read goes to the API server rather than
// caching every pod in the cluster on every node.
func TestWithoutANodeNameEveryReadHitsTheApiServer(t *testing.T) {
	fresh := pod("only-uid", "now")
	p := NewPods(context.Background(), fake.NewClientset(fresh), "")

	got, err := p.Get(context.Background(), "ns", "a-pod", "only-uid")
	if err != nil {
		t.Fatalf("Get: %v", err)
	}
	if string(got.UID) != "only-uid" {
		t.Fatalf("expected the pod from the API server, got UID %q", got.UID)
	}
}

package window

import (
	"context"
	"testing"
	"time"

	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/kubernetes/fake"
)

const volume = "secrets"

// apiPods is the trivial PodSource the tests use; production serves it from a watch.
type apiPods struct{ clientset kubernetes.Interface }

func (a apiPods) Get(ctx context.Context, namespace, name, _ string) (*corev1.Pod, error) {
	return a.clientset.CoreV1().Pods(namespace).Get(ctx, name, metav1.GetOptions{})
}

type container struct {
	name       string
	mounts     bool
	startedAgo time.Duration
	waiting    bool
	init       bool
}

func buildPod(startedAgo time.Duration, containers ...container) *corev1.Pod {
	start := metav1.NewTime(time.Now().Add(-startedAgo))
	pod := &corev1.Pod{
		ObjectMeta: metav1.ObjectMeta{Name: "a-pod", Namespace: "ns", CreationTimestamp: start},
		Status:     corev1.PodStatus{StartTime: &start},
	}
	for _, c := range containers {
		spec := corev1.Container{Name: c.name}
		if c.mounts {
			spec.VolumeMounts = []corev1.VolumeMount{{Name: volume, MountPath: "/mnt"}}
		}
		status := corev1.ContainerStatus{Name: c.name}
		if c.waiting {
			status.State = corev1.ContainerState{Waiting: &corev1.ContainerStateWaiting{}}
		} else {
			status.State = corev1.ContainerState{Running: &corev1.ContainerStateRunning{
				StartedAt: metav1.NewTime(time.Now().Add(-c.startedAgo)),
			}}
		}
		if c.init {
			pod.Spec.InitContainers = append(pod.Spec.InitContainers, spec)
			pod.Status.InitContainerStatuses = append(pod.Status.InitContainerStatuses, status)
		} else {
			pod.Spec.Containers = append(pod.Spec.Containers, spec)
			pod.Status.ContainerStatuses = append(pod.Status.ContainerStatuses, status)
		}
	}
	return pod
}

func isOpen(t *testing.T, p *corev1.Pod, duration time.Duration) bool {
	t.Helper()
	target := Pod{Namespace: "ns", Name: "a-pod", Volume: volume}
	open, err := IsOpen(context.Background(), apiPods{clientset: fake.NewClientset(p)}, target, duration)
	if err != nil {
		t.Fatalf("IsOpen: %v", err)
	}
	return open
}

func TestOpenRightAfterStart(t *testing.T) {
	p := buildPod(2*time.Second, container{name: "app", mounts: true, startedAgo: 2 * time.Second})
	if !isOpen(t, p, time.Minute) {
		t.Fatal("expected an open window")
	}
}

func TestClosedOnceTheWindowElapsed(t *testing.T) {
	p := buildPod(5*time.Minute, container{name: "app", mounts: true, startedAgo: 5 * time.Minute})
	if isOpen(t, p, time.Minute) {
		t.Fatal("expected a closed window")
	}
}

func TestOpenAtMountTimeBeforeAnyContainerRuns(t *testing.T) {
	// The driver publishes the volume before the containers start, so keying only on container start
	// would report a closed window exactly when the secrets are needed.
	p := buildPod(2*time.Second, container{name: "app", mounts: true, waiting: true})
	if !isOpen(t, p, time.Minute) {
		t.Fatal("expected an open window at mount time")
	}
}

func TestARestartReopensTheWindow(t *testing.T) {
	// The kubelet restarts a container in place and replays nothing, so the application comes back
	// needing its secrets. The fresh start time is what reopens the window, on a pod whose own start
	// time is long past.
	restarted := buildPod(5*time.Minute, container{name: "app", mounts: true, startedAgo: 2 * time.Second})
	if !isOpen(t, restarted, time.Minute) {
		t.Fatal("expected the window to reopen after the restart")
	}
}

func TestACrashLoopingNonConsumerDoesNotHoldTheWindowOpen(t *testing.T) {
	// The exposure this whole feature bounds. A sidecar that does not mount the volume restarting every
	// few seconds used to keep the window open for the pod's entire life, and code running in the pod
	// could trigger that deliberately.
	p := buildPod(1*time.Hour,
		container{name: "app", mounts: true, startedAgo: 1 * time.Hour},
		container{name: "metrics", mounts: false, startedAgo: 1 * time.Second},
	)
	if isOpen(t, p, time.Minute) {
		t.Fatal("a container that does not mount the volume must not reopen the window")
	}
}

func TestARestartedNativeSidecarConsumerReopensTheWindow(t *testing.T) {
	// Restartable init containers, the native sidecars of 1.29 and later, report through
	// InitContainerStatuses. A consumer there is as legitimate as one in Containers.
	p := buildPod(1*time.Hour,
		container{name: "app", mounts: false, startedAgo: 1 * time.Hour},
		container{name: "proxy", mounts: true, startedAgo: 2 * time.Second, init: true},
	)
	if !isOpen(t, p, time.Minute) {
		t.Fatal("a restarted native sidecar consumer must reopen the window")
	}
}

func TestNoIdentifiableConsumerFallsBackToPodStart(t *testing.T) {
	// Failing closed: without a volume name we cannot tell consumers apart, so the window rides the
	// pod's start time and shuts on schedule rather than being held open by something unrelated.
	p := buildPod(1*time.Hour, container{name: "app", mounts: true, startedAgo: 1 * time.Second})
	target := Pod{Namespace: "ns", Name: "a-pod"}
	open, err := IsOpen(context.Background(), apiPods{clientset: fake.NewClientset(p)}, target, time.Minute)
	if err != nil {
		t.Fatalf("IsOpen: %v", err)
	}
	if open {
		t.Fatal("expected the window to ride the pod start time when no consumer can be identified")
	}
}

package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"time"

	"github.com/infisical/infisical-csi-provider/internal/kube"
	"github.com/infisical/infisical-csi-provider/internal/server"
	"github.com/infisical/infisical-csi-provider/internal/version"
	"google.golang.org/grpc"
	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/rest"
	pb "sigs.k8s.io/secrets-store-csi-driver/provider/v1alpha1"
)

var (
	hostUrl    = flag.String("host-url", "https://app.infisical.com", "infisical instance URL")
	endpoint   = flag.String("endpoint", "/tmp/infisical.socket", "Path to socket on which to listen for driver gRPC calls.")
	healthPort = flag.String("health-port", "8080", "Port for HTTP health check.")
)

// ListenAndServe accepts incoming connections on a Unix socket. It is a blocking method.
// Returns non-nil error unless Close or Shutdown is called.
func listenAndServe(gs *grpc.Server) error {
	if !strings.HasPrefix(*endpoint, "@") {
		err := os.Remove(*endpoint)
		if err != nil && !os.IsNotExist(err) {
			return fmt.Errorf("failed to delete the socket file, error: %w", err)
		}
	}

	ln, err := net.Listen("unix", *endpoint)

	if err != nil {
		return err
	}
	defer ln.Close()

	// The watch lives as long as the listener does.
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	clientset, err := inClusterClientset()
	if err != nil {
		return fmt.Errorf("failed to create Kubernetes client: %w", err)
	}

	// NODE_NAME scopes the pod watch to this node. Without it the informer caches every pod in the
	// cluster, which a DaemonSet has no reason to do.
	pods := kube.NewPods(ctx, clientset, os.Getenv("NODE_NAME"))

	s := &server.Server{
		HostUrl: *hostUrl,
		Pods:    pods,
	}

	pb.RegisterCSIDriverProviderServer(gs, s)

	log.Printf("Listening on socket: %s\n", *endpoint)

	return gs.Serve(ln)
}

func shutdown(gs *grpc.Server) {
	if gs != nil {
		gs.GracefulStop()
	}
}

func startHealthCheck() chan error {
	mux := http.NewServeMux()
	ms := http.Server{
		Addr:    fmt.Sprintf(":%s", *healthPort),
		Handler: mux,
	}

	errorCh := make(chan error)

	mux.HandleFunc("/health/ready", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
	})

	log.Printf("Initializing health check %+v", *healthPort)

	go func() {
		defer func() {
			err := ms.Shutdown(context.Background())
			if err != nil {
				log.Printf("error shutting down health handler: %+v", err)
			}
		}()

		select {
		case errorCh <- ms.ListenAndServe():
		default:
		}
	}()

	return errorCh
}

func startProviderServer() chan error {
	gs := grpc.NewServer(
		grpc.ConnectionTimeout(20 * time.Second),
	)

	errorCh := make(chan error)
	log.Printf("Starting up provider server with build version: %s\n", version.BuildVersion)
	go func() {
		defer func() {
			shutdown(gs)
			close(errorCh)
		}()
		select {
		case errorCh <- listenAndServe(gs):
		default:
		}
	}()

	return errorCh
}

func realMain() error {
	signalsChan := make(chan os.Signal, 1)
	signal.Notify(signalsChan, syscall.SIGINT, syscall.SIGTERM)

	healthErrorChan := startHealthCheck()
	providerErrorChan := startProviderServer()

	for {
		select {
		case sig := <-signalsChan:
			return fmt.Errorf("captured %v, shutting down provider", sig)
		case providerErr := <-providerErrorChan:
			return providerErr
		case healthErr := <-healthErrorChan:
			return healthErr
		}
	}
}

func main() {
	flag.Parse()
	err := realMain()
	if err != nil {
		log.Printf("error running provider: %+v", err)
		os.Exit(1)
	}
}

// inClusterClientset builds the Kubernetes client used to evaluate read windows from pod status.
func inClusterClientset() (kubernetes.Interface, error) {
	config, err := rest.InClusterConfig()
	if err != nil {
		return nil, fmt.Errorf("failed to create in-cluster config: %w", err)
	}
	return kubernetes.NewForConfig(config)
}

package provider

import (
	"context"
	"fmt"
	"log"
	"strconv"
	"sync"

	infisical "github.com/infisical/go-sdk"
	"github.com/infisical/infisical-csi-provider/internal/config"
	"github.com/infisical/infisical-csi-provider/internal/window"
	pb "sigs.k8s.io/secrets-store-csi-driver/provider/v1alpha1"
)

// rotationReminder logs the driver-rotation requirement once per process, the first time a read
// window is evaluated. The window only ever closes when the driver re-invokes the provider, which it
// does only with secret rotation enabled; without it Mount is called once at publish time, when the
// window is always open, so the secret is served and never blanked. A MountRequest carries no signal
// of the driver's rotation setting, so this is a reminder rather than a check: it keeps the feature
// from silently doing nothing while an operator believes exposure is bounded.
var rotationReminder sync.Once

type Provider struct {
	pods window.PodSource
}

func NewProvider(pods window.PodSource) *Provider {
	return &Provider{pods: pods}
}

type secretItem struct {
	FileName string
	Value    string
	Version  string
}

func (p *Provider) HandleMountRequest(ctx context.Context, cfg config.Config) (*pb.MountResponse, error) {
	// Outside its read window a pod is served empty files, and Infisical is not called at all: the
	// secret never leaves the platform, rather than being fetched and then withheld.
	if cfg.Parameters.WindowDuration > 0 {
		rotationReminder.Do(func() {
			log.Print("windowDuration is set: the read window only takes effect when the driver runs with " +
				"--enable-secret-rotation=true and a short --rotation-poll-interval. Without rotation the provider " +
				"is called once at mount time, the window never closes, and secrets stay readable for the pod's whole life.")
		})
		open, err := window.IsOpen(ctx, p.pods, window.Pod{
			Namespace: cfg.Parameters.PodInfo.Namespace,
			Name:      cfg.Parameters.PodInfo.Name,
			UID:       string(cfg.Parameters.PodInfo.UID),
			Volume:    cfg.VolumeName,
		}, cfg.Parameters.WindowDuration)
		if err != nil {
			return nil, err
		}
		if !open {
			log.Printf("read window closed for pod %s/%s, serving empty files",
				cfg.Parameters.PodInfo.Namespace, cfg.Parameters.PodInfo.Name)
			return emptyResponse(cfg), nil
		}
	}

	infisicalUrl := cfg.Parameters.InfisicalUrl
	if infisicalUrl == "" {
		infisicalUrl = cfg.HostUrl
	}

	infisicalClient := infisical.NewInfisicalClient(ctx, infisical.Config{
		SiteUrl:       infisicalUrl,
		CaCertificate: cfg.Parameters.CaCertificate,
	})

	_, err := infisicalClient.Auth().KubernetesRawServiceAccountTokenLogin(cfg.Parameters.IdentityId, cfg.Parameters.PodInfo.ServiceAccountToken)
	if err != nil {
		return nil, fmt.Errorf("unable to login with Kubernetes auth [err=%s]", err)
	}

	secretMap := make(map[string]*secretItem)
	for _, secret := range cfg.Parameters.Secrets {
		sec, err := infisicalClient.Secrets().Retrieve(infisical.RetrieveSecretOptions{
			SecretKey:      secret.SecretKey,
			ProjectID:      cfg.Parameters.ProjectId,
			Environment:    cfg.Parameters.EnvSlug,
			SecretPath:     secret.SecretPath,
			IncludeImports: true,
		})

		if err != nil {
			return nil, err
		}

		secretMap[sec.ID] = &secretItem{
			FileName: secret.FileName,
			Value:    sec.SecretValue,
			Version:  fmt.Sprintf("%s-%s-%s-%s", sec.ID, sec.SecretPath, sec.SecretKey, strconv.Itoa(sec.Version)),
		}
	}

	var files []*pb.File
	var ov []*pb.ObjectVersion

	for _, value := range secretMap {
		files = append(files, &pb.File{Path: value.FileName, Mode: int32(cfg.FilePermission), Contents: []byte(value.Value)})
		ov = append(ov, &pb.ObjectVersion{Id: value.FileName, Version: value.Version})
		log.Printf("secret added to mount response, directory: %v, file: %v", cfg.TargetPath, value.FileName)
	}

	return &pb.MountResponse{
		ObjectVersion: ov,
		Files:         files,
	}, nil
}

// closedVersion is reported for every file while the window is shut. It is deliberately constant: the
// driver writes back whatever payload we return regardless of the version, and reporting a stable one
// keeps it from raising a rotation event and rewriting the pod status on every poll.
const closedVersion = "read-window-closed"

// emptyResponse serves every configured file with no content, so the driver overwrites what it
// previously wrote.
func emptyResponse(cfg config.Config) *pb.MountResponse {
	files := make([]*pb.File, 0, len(cfg.Parameters.Secrets))
	ov := make([]*pb.ObjectVersion, 0, len(cfg.Parameters.Secrets))
	for _, secret := range cfg.Parameters.Secrets {
		files = append(files, &pb.File{Path: secret.FileName, Mode: int32(cfg.FilePermission), Contents: []byte{}})
		ov = append(ov, &pb.ObjectVersion{Id: secret.FileName, Version: closedVersion})
	}
	return &pb.MountResponse{ObjectVersion: ov, Files: files}
}

package config

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"time"

	"gopkg.in/yaml.v2"
	authenticationv1 "k8s.io/api/authentication/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/types"
	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/rest"
	"sigs.k8s.io/secrets-store-csi-driver/pkg/util/fileutil"
)

type Config struct {
	Parameters     Parameters
	TargetPath     string
	FilePermission os.FileMode
	HostUrl        string
	// VolumeName is the CSI volume this mount publishes, recovered from TargetPath. The MountRequest
	// carries no volume field, and the driver itself parses the path the same way to correlate a target
	// path with a pod volume.
	VolumeName string
}

type PodInfo struct {
	Name                string
	UID                 types.UID
	Namespace           string
	ServiceAccountName  string
	ServiceAccountToken string
}

type Parameters struct {
	Audience           string
	UseDefaultAudience bool
	AuthMethod         string
	InfisicalUrl       string
	Secrets            []Secret
	PodInfo            PodInfo
	CaCertificate      string
	IdentityId         string
	ProjectId          string
	EnvSlug            string
	// WindowDuration bounds how long after its containers start a pod is served its secrets. Zero, the
	// default, serves them for the pod's whole life, which is the historical behaviour.
	WindowDuration time.Duration
}

type Secret struct {
	FileName   string `yaml:"fileName"`
	SecretPath string `yaml:"secretPath"`
	SecretKey  string `yaml:"secretKey"`
}

func createJWTTokenWithDefaultAudience(ctx context.Context, parameters Parameters) (string, error) {
	config, err := rest.InClusterConfig()
	if err != nil {
		return "", fmt.Errorf("failed to create in-cluster config: %w", err)
	}

	clientset, err := kubernetes.NewForConfig(config)
	if err != nil {
		return "", fmt.Errorf("failed to create Kubernetes client: %w", err)
	}

	podInfo := parameters.PodInfo
	ttl := int64((15 * time.Minute).Seconds())

	resp, err := clientset.CoreV1().ServiceAccounts(podInfo.Namespace).CreateToken(ctx, podInfo.ServiceAccountName, &authenticationv1.TokenRequest{
		Spec: authenticationv1.TokenRequestSpec{
			ExpirationSeconds: &ttl,
			BoundObjectRef: &authenticationv1.BoundObjectReference{
				Kind:       "Pod",
				APIVersion: "v1",
				Name:       podInfo.Name,
				UID:        podInfo.UID,
			},
		},
	}, metav1.CreateOptions{})

	if err != nil {
		return "", fmt.Errorf("failed to create a service account token for requesting pod %v: %w", podInfo, err)
	}

	return resp.Status.Token, nil
}

func parseParameters(ctx context.Context, parametersStr string) (Parameters, error) {
	var params map[string]string
	err := json.Unmarshal([]byte(parametersStr), &params)
	if err != nil {
		return Parameters{}, err
	}

	var parameters Parameters

	parameters.AuthMethod = params["authMethod"]

	// for now, only kubernetes auth is supported
	if parameters.AuthMethod != "kubernetes" {
		return Parameters{}, fmt.Errorf("invalid value for auth method - valid option is kubernetes")
	}

	parameters.Audience = params["audience"]
	if parameters.Audience == "" {
		parameters.Audience = "infisical"
	}

	parameters.UseDefaultAudience = params["useDefaultAudience"] == "true"

	parameters.InfisicalUrl = params["infisicalUrl"]
	parameters.CaCertificate = params["caCertificate"]
	parameters.IdentityId = params["identityId"]
	parameters.ProjectId = params["projectId"]
	parameters.EnvSlug = params["envSlug"]

	if raw := params["windowDuration"]; raw != "" {
		parameters.WindowDuration, err = time.ParseDuration(raw)
		if err != nil {
			return Parameters{}, fmt.Errorf("invalid windowDuration %q: %w", raw, err)
		}
		if parameters.WindowDuration <= 0 {
			return Parameters{}, fmt.Errorf("windowDuration must be positive, got %q", raw)
		}
	}

	parameters.PodInfo.Name = params["csi.storage.k8s.io/pod.name"]
	parameters.PodInfo.UID = types.UID(params["csi.storage.k8s.io/pod.uid"])
	parameters.PodInfo.Namespace = params["csi.storage.k8s.io/pod.namespace"]
	parameters.PodInfo.ServiceAccountName = params["csi.storage.k8s.io/serviceAccount.name"]

	tokensJSON := params["csi.storage.k8s.io/serviceAccount.tokens"]
	if tokensJSON != "" && !parameters.UseDefaultAudience {
		// The csi.storage.k8s.io/serviceAccount.tokens field is a JSON object
		// marshalled into a string. The object keys are audience name (string)
		// and the values are embedded objects with "token" property
		var tokens map[string]struct {
			Token string `json:"token"`
		}
		if err := json.Unmarshal([]byte(tokensJSON), &tokens); err != nil {
			return Parameters{}, fmt.Errorf("failed to unmarshal service account tokens: %w", err)
		}

		if token, ok := tokens[parameters.Audience]; ok {
			parameters.PodInfo.ServiceAccountToken = token.Token
		}
	}

	if parameters.UseDefaultAudience {
		parameters.PodInfo.ServiceAccountToken, err = createJWTTokenWithDefaultAudience(ctx, parameters)
		if err != nil {
			return Parameters{}, err
		}
	}

	if parameters.PodInfo.ServiceAccountToken == "" {
		return Parameters{}, fmt.Errorf("no service account token received")
	}

	secretsYaml := params["secrets"]
	if secretsYaml != "" {
		err = yaml.Unmarshal([]byte(secretsYaml), &parameters.Secrets)
		if err != nil {
			return Parameters{}, err
		}
	}

	return parameters, nil
}

func Parse(ctx context.Context, parametersStr string, targetPath string, permissionStr string, hostUrl string) (Config, error) {
	config := Config{
		TargetPath: targetPath,
		HostUrl:    hostUrl,
	}

	var err error
	config.Parameters, err = parseParameters(ctx, parametersStr)
	if err != nil {
		return Config{}, err
	}

	if err := json.Unmarshal([]byte(permissionStr), &config.FilePermission); err != nil {
		return Config{}, err
	}

	config.VolumeName = fileutil.GetVolumeNameFromTargetPath(targetPath)

	if config.Parameters.InfisicalUrl != "" {
		config.HostUrl = config.Parameters.InfisicalUrl
	}

	err = config.Validate()
	if err != nil {
		return Config{}, err
	}

	return config, nil
}

func (cfg *Config) Validate() error {
	if cfg.HostUrl == "" {
		return fmt.Errorf("infisical url must be defined")
	}

	if cfg.Parameters.IdentityId == "" {
		return fmt.Errorf("identity id must be defined")
	}

	if cfg.Parameters.ProjectId == "" {
		return fmt.Errorf("project id must be defined")
	}

	if cfg.Parameters.EnvSlug == "" {
		return fmt.Errorf("env slug must be defined")
	}

	if len(cfg.Parameters.Secrets) == 0 {
		return fmt.Errorf("must have at least one secret")
	}

	return nil
}

// Package kube serves pod lookups, from a watch when it can and from the API server otherwise.
//
// With rotation enabled the driver calls Mount for every pod on every poll, so a plain request per
// call is one API call per pod per interval per node. A shared informer collapses that to one watch,
// scoped by field selector to the node this DaemonSet pod runs on.
package kube

import (
	"context"
	"fmt"
	"log"

	corev1 "k8s.io/api/core/v1"
	apierrors "k8s.io/apimachinery/pkg/api/errors"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/fields"
	"k8s.io/client-go/informers"
	"k8s.io/client-go/kubernetes"
	listers "k8s.io/client-go/listers/core/v1"
)

// Pods reads pods, preferring a watch of this node's pods when one is running.
type Pods struct {
	clientset kubernetes.Interface
	// lister is nil when no node name was available to scope a watch, in which case every read goes to
	// the API server.
	lister listers.PodLister
}

// NewPods watches the pods scheduled on nodeName.
//
// An empty nodeName leaves the watch unstarted and reads go straight to the API server. That keeps an
// image upgrade from breaking a deployment whose manifests do not set NODE_NAME yet, and avoids the
// alternative of caching every pod in the cluster on every node.
//
// It does not block on the initial sync. The driver publishes a volume very early in a pod's life, so
// a cold cache is a normal state rather than an error, and Get falls back on a miss.
func NewPods(ctx context.Context, clientset kubernetes.Interface, nodeName string) *Pods {
	if nodeName == "" {
		log.Print("NODE_NAME is not set, reading pods from the API server instead of a watch")
		return &Pods{clientset: clientset}
	}

	factory := informers.NewSharedInformerFactoryWithOptions(clientset, 0,
		informers.WithTweakListOptions(func(o *metav1.ListOptions) {
			o.FieldSelector = fields.OneTermEqualSelector("spec.nodeName", nodeName).String()
		}))
	informer := factory.Core().V1().Pods()
	lister := informer.Lister()
	factory.Start(ctx.Done())

	return &Pods{clientset: clientset, lister: lister}
}

// Get returns a pod, preferring the cache.
//
// A cached object whose UID does not match is treated as a miss. Names get reused: deleting a pod and
// recreating it under the same name leaves the cache briefly holding the old object, whose start time
// belongs to a lifetime that has ended, and trusting it reports a long-closed window for a pod that
// just started.
//
// Only a miss falls back. Any other lister error means the watch is unhealthy, and silently reverting
// to a request per mount would undo the point of the watch without saying so.
func (p *Pods) Get(ctx context.Context, namespace, name, uid string) (*corev1.Pod, error) {
	if p.lister == nil {
		return p.fromApiServer(ctx, namespace, name, uid)
	}

	pod, err := p.lister.Pods(namespace).Get(name)
	if err != nil && !apierrors.IsNotFound(err) {
		return nil, fmt.Errorf("pod watch is unhealthy: %w", err)
	}
	if err == nil && (uid == "" || string(pod.UID) == uid) {
		return pod, nil
	}
	return p.fromApiServer(ctx, namespace, name, uid)
}

// fromApiServer reads the pod live, and rejects a name that now resolves to a different incarnation.
//
// A name can be reused, so the pod the API server returns may be the replacement of the one the mount
// was created for. Evaluating the window against the replacement's fresh start time would serve
// secrets to a mount from a lifetime that has ended, so a UID mismatch is reported as not found and
// the caller fails closed, exactly as it does for a pod that is simply gone. This mirrors the UID
// check on the cache path; without it that guard is only as good as the teardown race that hides the
// gap.
func (p *Pods) fromApiServer(ctx context.Context, namespace, name, uid string) (*corev1.Pod, error) {
	pod, err := p.clientset.CoreV1().Pods(namespace).Get(ctx, name, metav1.GetOptions{})
	if err != nil {
		return nil, err
	}
	if uid != "" && string(pod.UID) != uid {
		return nil, apierrors.NewNotFound(corev1.Resource("pods"), name)
	}
	return pod, nil
}

package server

import (
	"context"
	"fmt"

	"github.com/infisical/infisical-csi-provider/internal/config"
	"github.com/infisical/infisical-csi-provider/internal/provider"
	"github.com/infisical/infisical-csi-provider/internal/version"
	"github.com/infisical/infisical-csi-provider/internal/window"
	pb "sigs.k8s.io/secrets-store-csi-driver/provider/v1alpha1"
)

var _ pb.CSIDriverProviderServer = (*Server)(nil)

// Server implements the secrets-store-csi-driver provider gRPC service interface.
type Server struct {
	HostUrl string
	// Pods reads pod status to evaluate the read window, from a watch rather than a request per
	// mount: the rotation reconciler calls Mount for every pod on every poll.
	Pods window.PodSource
}

func (s *Server) Version(context.Context, *pb.VersionRequest) (*pb.VersionResponse, error) {
	return &pb.VersionResponse{
		Version:        "v1alpha1",
		RuntimeName:    "infisical-csi-provider",
		RuntimeVersion: version.BuildVersion,
	}, nil
}

func (s *Server) Mount(ctx context.Context, req *pb.MountRequest) (*pb.MountResponse, error) {
	cfg, err := config.Parse(ctx, req.Attributes, req.TargetPath, req.Permission, s.HostUrl)
	if err != nil {
		return nil, err
	}

	provider := provider.NewProvider(s.Pods)
	resp, err := provider.HandleMountRequest(ctx, cfg)
	if err != nil {
		return nil, fmt.Errorf("error making mount request: %w", err)
	}
	return resp, nil
}

// Package window bounds how long a pod may read its mounted secrets.
//
// A pod that can read its secrets for its whole life hands the same access to anything that later
// achieves code execution inside it. Serving the secrets only while the containers are freshly
// started shrinks that to a window around startup, which is when the application actually needs
// them.
//
// The window is evaluated from the pod's own status in the API server, which the pod cannot forge.
package window

import (
	"context"
	"fmt"
	"time"

	corev1 "k8s.io/api/core/v1"
)

// PodSource reads a pod by namespace and name. Implemented by internal/kube.
//
// The uid identifies which incarnation of that name is wanted, and may be empty. It matters because a
// pod can be replaced by a new one with the same name, and a cache still holding the old object would
// otherwise answer with a start time from the previous pod's lifetime.
type PodSource interface {
	Get(ctx context.Context, namespace, name, uid string) (*corev1.Pod, error)
}

// Pod identifies the mount being evaluated.
type Pod struct {
	Namespace string
	Name      string
	UID       string
	// Volume is the CSI volume this mount publishes. The window follows the containers that mount it,
	// so an unrelated container restarting cannot reopen it. When empty, or when nothing mounts it, the
	// window rides the pod's own start time and closes on schedule rather than risking being held open
	// by something else.
	Volume string
}

// IsOpen reports whether the containers consuming this volume entered their current run less than
// duration ago.
//
// The reference is the most recent of the pod's start time and the start of a consuming container.
// The pod's start time is what matters at mount time, because the driver publishes the volume before
// any container runs, so keying only on container start would report a closed window exactly when the
// secrets are needed. A consumer restarted in place gets a fresh start time, and that is what reopens
// the window for it: the kubelet replays nothing on its behalf, so the application comes back needing
// its secrets again.
//
// Only consumers count. A sidecar that does not mount the volume and happens to crash loop would
// otherwise hold the window open for the pod's whole life, which is the exact exposure this is meant
// to bound, and something code running in the pod could trigger deliberately.
func IsOpen(ctx context.Context, pods PodSource, target Pod, duration time.Duration) (bool, error) {
	pod, err := pods.Get(ctx, target.Namespace, target.Name, target.UID)
	if err != nil {
		return false, fmt.Errorf("unable to read pod %s/%s: %w", target.Namespace, target.Name, err)
	}

	// Very early in a pod's life the status is not populated yet.
	startedAt := pod.CreationTimestamp.Time
	if pod.Status.StartTime != nil {
		startedAt = pod.Status.StartTime.Time
	}
	// Whichever consumer started last carries the window, so a pod whose containers come up at slightly
	// different times still gets one window covering all of them.
	if consumer := latestConsumerStart(pod, target.Volume); consumer.After(startedAt) {
		startedAt = consumer
	}

	return time.Since(startedAt) < duration, nil
}

// latestConsumerStart returns the most recent start time among running containers that mount volume,
// or the zero time when none do.
//
// The spec and status slices are walked in step rather than concatenated: they belong to an object the
// informer cache shares with every caller, and appending one onto the other would write into its
// backing array.
func latestConsumerStart(pod *corev1.Pod, volume string) time.Time {
	var latest time.Time
	consider := func(containers []corev1.Container, statuses []corev1.ContainerStatus) {
		for _, container := range containers {
			if !mountsVolume(container, volume) {
				continue
			}
			for _, status := range statuses {
				if status.Name != container.Name {
					continue
				}
				if running := status.State.Running; running != nil && running.StartedAt.After(latest) {
					latest = running.StartedAt.Time
				}
				break
			}
		}
	}

	consider(pod.Spec.Containers, pod.Status.ContainerStatuses)
	// Restartable init containers, the native sidecars of 1.29 and later, run alongside the app and
	// report separately, so a consumer can legitimately live there.
	consider(pod.Spec.InitContainers, pod.Status.InitContainerStatuses)
	return latest
}

func mountsVolume(container corev1.Container, volume string) bool {
	for _, mount := range container.VolumeMounts {
		if mount.Name == volume {
			return true
		}
	}
	return false
}
